        def __init__(self, nodes):
            self.nodes = nodes
            self.docstore = type('DocStore', (), {'docs': {n.id_: n for n in nodes}})
        def as_retriever(self, filters=None, similarity_top_k=1):
            class Retriever:
                def __init__(self, nodes, filters):
                    self.nodes = nodes
                    self.filters = filters
