                    if self.filters is None:
                        return self.nodes[:similarity_top_k]
                    # simple filter: assume filters.filters list with one filter having key,value
                    for f in self.filters.filters:
                        key = f.key
                        val = f.value
                        matched = [n for n in self.nodes if n.metadata.get(key) == val]
                        return matched[:similarity_top_k]
                    return []
            return Retriever(self.nodes, filters)
    class MetadataFilter:
        def __init__(self, key, operator=None, value=None):
            self.key = key
            self.value = value
    class MetadataFilters:
        def __init__(self, filters):
            self.filters = filters
    class FilterOperator:
        EQ = None
    class DummyEmbedding:
        def embed(self, text):
            return [0.0]*1536
